<script>
  import Icon from '../../Icon/Icon.svelte'
  import { close, getDisclosure } from './disclosure.svelte.js'

  const {
    class: klass = '',
    icon = 'tabler:x',
    iconClass = '',
    target = '',
    children,
    ...rest
  } = $props()

  let button = null

  function closeDrawer() {
    const id =
      document.querySelector(`${target}`)?.id ||
      button.closest('.disclosure-content').id
    const d = getDisclosure(id)
    close(d, { shouldFocusWhenClosing: true })
  }
</script>

<button
  aria-label="Close"
  class="button-icon {klass}"
  {...rest}
  bind:this={button}
  onclick={closeDrawer}
>
  {#if children}
    {@render children()}
  {:else}
    <Icon class={iconClass} {icon} />
  {/if}
</button>
